package com.tyes.civilisation.brain.decision;
import com.tyes.civilisation.brain.*;import com.tyes.civilisation.brain.task.BuilderTask;import com.tyes.civilisation.server.CivilisationServices;import com.tyes.civilisation.settlement.WorkRole;import java.util.Optional;
public final class ConstructionDecisionProvider implements DecisionProvider {public Optional<DecisionCandidate> evaluate(CitizenBrain b){if(!b.record().development().lifeStage().mayPerformFullWork()||b.record().settlementId().isEmpty()||b.record().needs().isCriticallyHungry()||b.record().needs().isCriticallyTired()||!CitizenSchedule.isWorkTime(b.level().getDayTime(),b.scheduleJitter())||!(b.record().workRole()==WorkRole.GENERAL_LABOURER||b.record().workRole()==WorkRole.CRAFTER||b.record().workRole()==WorkRole.HAULER||b.record().workRole()==WorkRole.BUILDER||b.record().development().career()==WorkRole.BUILDER)||!b.isTaskAvailable(BuilderTask.TYPE))return Optional.empty();return CivilisationServices.construction(b.level().getServer()).claim(b.record()).map(c->new DecisionCandidate(new BuilderTask(c),switch(c.priority()){case CRITICAL->860;case HIGH->820;case NORMAL->740;case LOW->650;},"physical construction placement ("+c.priority()+")"));}}
